<script setup lang="ts">import{Head,Link,router}from'@inertiajs/vue3';import{reactive}from'vue';import PageHeader from '@/Components/Shared/PageHeader.vue';import{Button}from'@/components/ui/button';const props=defineProps<{leads:any[],filters:any}>();const f=reactive({search:props.filters.search??'',stage:props.filters.stage??''});const apply=()=>router.get('/admin/sponsorship-leads',f,{preserveState:true});</script><template><Head title="Sponsorship Sales Pipeline"/><div class="space-y-6 p-6"><div class="flex justify-between"><PageHeader title="Sponsorship Sales Pipeline" description="Track leads, follow-ups, probability, and expected value."/><Link href="/admin/sponsorship-leads/create"><Button>Add Lead</Button></Link></div><form @submit.prevent="apply" class="flex gap-2 rounded-xl border p-4"><input v-model="f.search" placeholder="Search leads" class="rounded-md border p-2"/><select v-model="f.stage" class="rounded-md border p-2"><option value="">All stages</option><option v-for="s in ['new','contacted','qualified','proposal','negotiation','won','lost']" :key="s">{{s}}</option></select><Button>Apply</Button></form><div class="overflow-hidden rounded-xl border"><table class="w-full text-sm"><thead><tr><th class="p-3 text-left">Company</th><th>Stage</th><th>Owner</th><th>Probability</th><th>Follow-up</th></tr></thead><tbody><tr v-for="l in leads" :key="l.id" class="border-t"><td class="p-3"><Link :href="`/admin/sponsorship-leads/${l.id}`" class="font-medium hover:underline">{{l.company_name}}</Link><div class="text-muted-foreground">{{l.contact_name}}</div></td><td>{{l.stage}}</td><td>{{l.owner?.name??'Unassigned'}}</td><td>{{l.probability}}%</td><td>{{l.next_follow_up_at??'—'}}</td></tr></tbody></table></div></div></template>